onComplete.script:
var p = mc.getPayloadJSON();
var quedan = {}; var q = (p && p.ots && p.ots.ot) ? p.ots.ot : [];
if (!(q instanceof Array)) { q = [q]; }
for (var i = 0; i < q.length; i++) { quedan[String(q[i].id_orden)] = true; }
var pedidas = JSON.parse(String(mc.getProperty("man_ots_pedidas")));
if (!(pedidas instanceof Array)) { pedidas = [pedidas]; }
var r = [];
for (var j = 0; j < pedidas.length; j++) {
   var id = String(pedidas[j].id_orden);
   if (quedan[id]) { r.push({"status": false, "id_orden": id, "msj": "La orden sigue sin lanzar"}); }
   else { r.push({"status": true, "id_orden": id}); }
}
mc.setPayloadJSON({"status": true, "resultado": r});

inSequence.script:
var p = mc.getPayloadJSON(); var it = (p && p.items) ? p.items : []; var ok = [];
           for (var i = 0; i < it.length; i++) { var a = String(it[i].arti_id), c = String(it[i].cantidad); if (/^[0-9]+$/.test(a) && /^[0-9]+([.][0-9]+)?$/.test(c) && parseFloat(c) > 0) { ok.push({"arti_id": a, "cantidad": c}); } }
           mc.setProperty("man_items", JSON.stringify(ok)); mc.setProperty("man_nitems", String(ok.length));

then.script:
var it = JSON.parse(mc.getProperty("man_items")); var pema = String(mc.getProperty("man_pema")); var d = [];
           for (var i = 0; i < it.length; i++) { d.push({"cantidad": it[i].cantidad, "pema_id": pema, "arti_id": it[i].arti_id}); }
           mc.setPayloadJSON({"_post_pedidos_detalle_batch_req": {"_post_pedidos_detalle": d}});
